#!/bin/bash
set -euo pipefail

THRESHOLD="${THRESHOLD:-80}"

df -iP | awk -v threshold="$THRESHOLD" '
NR > 1 {
    usage=$5
    gsub("%","",usage)
    if (usage >= threshold)
        printf "WARNING: %s inode usage is %s%%\n", $6, usage
    else
        printf "OK: %s inode usage is %s%%\n", $6, usage
}'
